(()=>{function boot(){const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;document.querySelectorAll('[data-gsap-slider]').forEach(root=>{const cards=[...root.querySelectorAll(':scope>a')];if(cards.length<2)return;let active=0,timer;function go(index,manual){active=(index+cards.length)%cards.length;const x=cards[active].offsetLeft-root.offsetLeft;if(window.gsap&&!reduce)window.gsap.to(root,{scrollLeft:x,duration:.62,ease:'power2.inOut',overwrite:true});else root.scrollTo({left:x,behavior:reduce?'auto':'smooth'});if(manual)restart()}function restart(){clearInterval(timer);if(!reduce)timer=setInterval(()=>go(active+1,false),7600)}const controls=document.createElement('div');controls.className='pinned-brief-slider-controls';controls.setAttribute('aria-label','Pinned brief controls');controls.innerHTML='<button type="button" aria-label="Previous brief">‹</button><button type="button" aria-label="Next brief">›</button>';controls.children[0].onclick=()=>go(active-1,true);controls.children[1].onclick=()=>go(active+1,true);root.after(controls);root.addEventListener('pointerdown',()=>clearInterval(timer),{passive:true});root.addEventListener('pointerup',restart,{passive:true});if(window.gsap&&!reduce)window.gsap.fromTo(cards,{autoAlpha:0,y:18},{autoAlpha:1,y:0,duration:.7,stagger:.1,ease:'power3.out',clearProps:'transform,opacity,visibility'});restart()})}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot);else boot()})();